import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const root = new Group();
  const resources = [];
  const timelines = [];
  const primitiveResults = [];

  root.userData.handlers = {};

  const ink = new Color('#16161d');
  const paper = new Color('#e8ecf2');
  const accent = new Color('#ff2a38');
  const surface = new Color('#0b0b10');

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropUv = uv();
  const verticalGradient = smoothstep(0.02, 0.98, backdropUv.y);
  backdropMaterial.colorNode = mix(
    vec3(surface.r, surface.g, surface.b),
    vec3(ink.r, ink.g, ink.b),
    verticalGradient
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const cardGeometry = new PlaneGeometry(3.15, 1.975);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.96
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.set(0, 0, -0.2);
  root.add(card);
  resources.push(cardGeometry, cardMaterial);

  const imageGeometry = new PlaneGeometry(2.86, 1.79);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true
  });
  const image = new Mesh(imageGeometry, imageMaterial);
  image.position.set(0, 0, 0);
  root.add(image);
  resources.push(imageGeometry, imageMaterial);

  const topBarGeometry = new PlaneGeometry(0.72, 0.035);
  const topBarMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  const topBar = new Mesh(topBarGeometry, topBarMaterial);
  topBar.position.set(-1.02, 0.82, 0.08);
  root.add(topBar);
  resources.push(topBarGeometry, topBarMaterial);

  const cornerGeometry = new PlaneGeometry(0.035, 0.42);
  const cornerMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  const corner = new Mesh(cornerGeometry, cornerMaterial);
  corner.position.set(1.39, -0.66, 0.08);
  root.add(corner);
  resources.push(cornerGeometry, cornerMaterial);

  const atlas = config.atlasRegion ?? {
    x: 0,
    y: 0,
    width: 512,
    height: 320
  };

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!texture) return;

      resources.push(texture);

      const imageData = texture.image;
      const atlasWidth = imageData?.width || atlas.width;
      const atlasHeight = imageData?.height || atlas.height;

      texture.wrapS = THREE.ClampToEdgeWrapping;
      texture.wrapT = THREE.ClampToEdgeWrapping;
      texture.repeat.set(
        atlas.width / atlasWidth,
        atlas.height / atlasHeight
      );
      texture.offset.set(
        atlas.x / atlasWidth,
        1 - (atlas.y + atlas.height) / atlasHeight
      );
      texture.needsUpdate = true;

      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    });
  }

  const billboardMeshes = [backdrop, card, image, topBar, corner];
  for (const mesh of billboardMeshes) {
    mesh.onBeforeRender = (_renderer, camera) => {
      if (camera?.quaternion) mesh.quaternion.copy(camera.quaternion);
    };
  }

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    root.scale,
    { x: 0.97, y: 0.97, z: 0.97 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out'
    }
  );
  entrance.fromTo(
    root,
    { positionZ: -0.16 },
    {
      positionZ: 0,
      duration: 0.7,
      ease: 'power3.out'
    },
    '<'
  );
  entrance.play();
  timelines.push(entrance);

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result) {
        primitiveResults.push(result);
        if (result.timeline) timelines.push(result.timeline);
      }
    }
  }

  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const result of primitiveResults) {
      if (result?.cleanup) result.cleanup();
    }

    for (const resource of resources) {
      if (resource?.dispose) resource.dispose();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];

        for (const material of materials) {
          if (material?.dispose) material.dispose();
        }
      }
    });
  };

  return root;
}
